<template><section class="refund-requests"><h2>Payer refund requests</h2><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="!requests.length">No refund requests awaiting review.</p><article v-for="request in requests" :key="request.requestId"><h3>Request {{ request.requestId }} · {{ request.receiptNumber }}</h3><p>{{ money(request.amountCents) }} · {{ request.status }} · Service {{ String(request.serviceDate||'').slice(0,10) }}</p><p>{{ request.reason }}</p><p>Verify that the session did not occur and review any applied credit. Approving submits the refund to Stripe for a card payment. For cash, approve only after returning the money. Applied credits are reversed and the affected visit is held for billing review.</p><label>Billing review / response<textarea v-model="reasons[request.requestId]" rows="3" maxlength="2000" /></label><button :disabled="busy||!reasons[request.requestId]?.trim()" @click="resolve(request,true)">{{ request.status==='requested'?'Approve and issue refund':'Reconcile same refund' }}</button><button v-if="request.status==='requested'" :disabled="busy||!reasons[request.requestId]?.trim()" @click="resolve(request,false)">Decline with response</button></article><h3 v-if="deliveries.length">Receipt delivery needs attention</h3><p v-for="delivery in deliveries" :key="delivery.id">{{ delivery.receiptNumber }} · {{ delivery.kind.replaceAll('_',' ') }} · {{ delivery.status }} · Communication {{ delivery.communicationId||'not yet created' }}</p><p v-if="deliveries.length">Check the communication log before resending any message with uncertain delivery. Payers can still download their receipt in Billing.</p></section></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({agencyId:[Number,String]}),emit=defineEmits(['updated']);
const requests=ref([]),deliveries=ref([]),reasons=ref({}),busy=ref(false),error=ref(''),message=ref('');let sequence=0;
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)/100);
async function load(){const own=++sequence;requests.value=[];deliveries.value=[];if(!props.agencyId)return;try{const results=await Promise.all(['/refund-requests','/receipt-deliveries'].map(path=>api.get(`/family-billing/staff${path}`,{params:{agencyId:props.agencyId}})));if(own===sequence){requests.value=results[0].data.requests;deliveries.value=results[1].data.deliveries;}}catch{if(own===sequence)error.value='Refund requests could not be loaded.';}}
async function resolve(request,approve){busy.value=true;error.value='';message.value='';try{const {data}=await api.post(`/family-billing/staff/refund-requests/${request.requestId}/resolve`,{agencyId:props.agencyId,approve,reason:reasons.value[request.requestId]});message.value=data.refunded?'Refund confirmed.':data.declined?'Request declined with your response.':'Refund is awaiting processor confirmation. Reconcile this same request; do not create another refund.';await load();emit('updated');}catch(e){error.value=e.response?.data?.error?.message||'Refund needs reconciliation. Do not submit a separate refund.';}finally{busy.value=false;}}
watch(()=>props.agencyId,()=>{reasons.value={};error.value='';message.value='';void load();},{immediate:true});
</script>
<style scoped>.refund-requests{padding:24px;border:1px solid var(--border,#dce4ed);border-radius:10px;margin:20px 0}.refund-requests article{padding:20px 0;border-bottom:1px solid var(--border,#dce4ed)}textarea{display:block;width:100%;box-sizing:border-box;margin:8px 0 16px;padding:10px;font:inherit}button{margin:4px 10px 4px 0;padding:10px 16px;cursor:pointer}button:disabled{opacity:.5}</style>
